import Foundation
@main struct HeartbeatChecks {
    static func main() throws {
        let now=Date(timeIntervalSince1970:1_791_280_000)
        var account=PAHeartbeatAccount()
        precondition(PAHeartbeatRules.due(account,now:now))
        account.checked=now
        precondition(!PAHeartbeatRules.due(account,now:now.addingTimeInterval(1799),minutes:30))
        precondition(PAHeartbeatRules.due(account,now:now.addingTimeInterval(1800),minutes:30))
        account.fingerprint="same"
        precondition(!PAHeartbeatRules.needsAssessment(account,fingerprint:"same",manual:false))
        precondition(PAHeartbeatRules.needsAssessment(account,fingerprint:"same",manual:false,pendingSources:true))
        precondition(PAHeartbeatRules.needsAssessment(account,fingerprint:"new",manual:false))
        account.phase="assessing"
        let recovered=PAHeartbeatRules.recovered(account)
        precondition(recovered.phase == "paused" && recovered.checked == account.checked && recovered.fingerprint == "same")
        precondition(!PAHeartbeatRules.needsAssessment(recovered,fingerprint:"new",manual:false))
        precondition(!PAHeartbeatRules.needsAssessment(recovered,fingerprint:"same",manual:false,pendingSources:true))
        precondition(PAHeartbeatRules.needsAssessment(recovered,fingerprint:"same",manual:true,pendingSources:true))
        precondition(PAHeartbeatRules.needsAssessment(recovered,fingerprint:"new",manual:true))
        var state=PAHeartbeatState(accounts:["a":recovered,"b":PAHeartbeatAccount()])
        state=try JSONDecoder().decode(PAHeartbeatState.self,from:JSONEncoder().encode(state))
        precondition(state.accounts["a"]?.phase == "paused" && PAHeartbeatRules.due(state.accounts["b"]!,now:now))
        precondition(!PAHeartbeatRules.due(account,now:now.addingTimeInterval(3599),minutes:60))
        precondition(PAHeartbeatRules.due(account,now:now.addingTimeInterval(3600),minutes:60))
        precondition(PAHeartbeatRules.due(account,now:now.addingTimeInterval(900),minutes:15))
        var budget=PAHeartbeatAccount()
        budget=try PAHeartbeatRules.claim(budget,day:"2026-10-06",limit:2)
        budget=try PAHeartbeatRules.claim(budget,day:"2026-10-06",limit:2)
        do { _ = try PAHeartbeatRules.claim(budget,day:"2026-10-06",limit:2);preconditionFailure("Allowance exceeded") } catch is HeartbeatBudgetExhausted {}
        precondition(PAHeartbeatRules.callCount(budget,day:"2026-10-06") == 2)
        budget.pending=true
        precondition(PAHeartbeatRules.needsAssessment(budget,fingerprint:budget.fingerprint ?? "",manual:false))
        budget.phase="paused"
        precondition(!PAHeartbeatRules.needsAssessment(budget,fingerprint:"new",manual:false))
        budget.phase="idle"
        let next=try PAHeartbeatRules.claim(budget,day:"2026-10-07",limit:2)
        precondition(next.calls == 1 && next.budgetDay == "2026-10-07")
        let savedBudget=try JSONDecoder().decode(PAHeartbeatAccount.self,from:JSONEncoder().encode(budget))
        precondition(savedBudget.calls == 2 && savedBudget.phase == "idle")
        var lanes=PAHeartbeatRules.collectingMail(budget,enabled:["healthy","failed"],ready:["healthy"],issues:["failed":"timeout"],now:now)
        lanes=PAHeartbeatRules.completedMail(lanes,fingerprints:["healthy":"opaque-v1"],pending:[],now:now)
        precondition(lanes.mailLanes?["healthy"]?.assessed == now && lanes.mailLanes?["healthy"]?.pending == false)
        precondition(lanes.mailLanes?["failed"]?.assessed == nil && lanes.mailLanes?["failed"]?.issue == "timeout" && lanes.mailLanes?["failed"]?.pending == true)
        let reopened=try JSONDecoder().decode(PAHeartbeatAccount.self,from:JSONEncoder().encode(lanes))
        precondition(reopened.mailLanes?["healthy"]?.fingerprint == "opaque-v1" && reopened.mailLanes?["failed"]?.issue == "timeout")
        lanes=PAHeartbeatRules.collectingMail(reopened,enabled:["healthy","failed"],ready:["healthy","failed"],issues:[:],now:now.addingTimeInterval(3600))
        precondition(lanes.mailLanes?["failed"]?.pending == true && lanes.mailLanes?["failed"]?.assessed == nil,"Collection alone never marks failed account assessed")
        lanes=PAHeartbeatRules.completedMail(lanes,fingerprints:["failed":"opaque-recovered"],pending:["failed"],now:now.addingTimeInterval(3600))
        precondition(lanes.mailLanes?["failed"]?.assessed == now.addingTimeInterval(3600) && lanes.mailLanes?["healthy"]?.assessed == now)
        let stopped=PAHeartbeatRules.recovered(PAHeartbeatAccount(phase:"assessing",mailLanes:lanes.mailLanes))
        precondition(stopped.phase == "paused" && stopped.mailLanes?["failed"]?.fingerprint == "opaque-recovered")
        let narrowed=PAHeartbeatRules.collectingMail(lanes,enabled:["healthy"],ready:["healthy"],issues:[:],now:now)
        precondition(narrowed.mailLanes?.count == 1 && narrowed.calls == lanes.calls)
        let legacy=try JSONDecoder().decode(PAHeartbeatAccount.self,from:Data(#"{"phase":"idle"}"#.utf8))
        precondition(legacy.mailLanes == nil)
        let run=PAReviewRun(id:"run",started:now,finished:now,manual:true,phase:"paused",detail:"Rejected target",calls:2,checkedAccounts:1,waitingAccounts:1,preparedItems:0,drafts:1,handled:0)
        let activity=try JSONDecoder().decode(PAHeartbeatAccount.self,from:JSONEncoder().encode(PAHeartbeatAccount(phase:"paused",reviews:[run])))
        precondition(activity.reviews?.first?.calls == 2 && activity.reviews?.first?.detail == "Rejected target" && legacy.reviews == nil)
        let interruptedCollection=PAHeartbeatRules.interrupted(PAHeartbeatAccount(checked:now,phase:"refreshing",budgetDay:"2026-10-06",calls:1,mailLanes:lanes.mailLanes,reviews:[run]),now:now,foreground:true)
        precondition(interruptedCollection.phase == "idle" && interruptedCollection.pending == true && interruptedCollection.retryReason == "foreground")
        precondition(!PAHeartbeatRules.due(interruptedCollection,now:now.addingTimeInterval(59)))
        precondition(PAHeartbeatRules.due(interruptedCollection,now:now.addingTimeInterval(60)),"An idle retry must not consume a whole hourly review interval")
        precondition(interruptedCollection.calls == 1 && interruptedCollection.mailLanes?["failed"]?.fingerprint == lanes.mailLanes?["failed"]?.fingerprint && interruptedCollection.reviews?.first?.id == run.id)
        let restoredCollection=PAHeartbeatRules.recovered(PAHeartbeatAccount(checked:now,phase:"refreshing"),now:now)
        precondition(restoredCollection.phase == "idle" && restoredCollection.retryAfter == now.addingTimeInterval(300))
        let interruptedInference=PAHeartbeatRules.interrupted(PAHeartbeatAccount(checked:now,phase:"assessing",retryAfter:now),now:now,foreground:true)
        precondition(interruptedInference.phase == "paused" && interruptedInference.retryAfter == nil)
        precondition(!PAHeartbeatRules.needsAssessment(interruptedInference,fingerprint:"changed",manual:false,pendingSources:true),"A scheduled retry must never resume interrupted inference")
        precondition(PAHeartbeatRules.deferred(interruptedInference,now:now,reason:.foreground).phase == "paused")
        var london=Calendar(identifier:.gregorian);london.timeZone=TimeZone(identifier:"Europe/London")!
        let formatter=ISO8601DateFormatter(),nearMidnight=formatter.date(from:"2026-10-06T22:58:00Z")!,midnight=formatter.date(from:"2026-10-06T23:00:00Z")!
        let exhausted=PAHeartbeatRules.deferred(PAHeartbeatAccount(checked:nearMidnight,budgetDay:"2026-10-06",calls:2),now:nearMidnight,reason:.allowance,calendar:london)
        precondition(exhausted.retryAfter == midnight && exhausted.pending == true)
        precondition(!PAHeartbeatRules.due(exhausted,now:midnight.addingTimeInterval(-1),day:"2026-10-06"))
        precondition(PAHeartbeatRules.due(exhausted,now:midnight,day:"2026-10-07"),"Day rollover must release pending allowance work without waiting another hour")
        precondition(PAHeartbeatRules.due(exhausted,now:nearMidnight,day:"2026-10-07"),"A timezone change must follow the current local allowance day")
        precondition(PAHeartbeatRules.due(exhausted,now:nearMidnight,day:"2026-10-06",allowance:3),"An explicitly raised allowance releases waiting work")
        let dstDay=formatter.date(from:"2026-10-25T00:30:00Z")!
        let dst=PAHeartbeatRules.deferred(PAHeartbeatAccount(budgetDay:"2026-10-25",calls:2),now:dstDay,reason:.allowance,calendar:london)
        precondition(dst.retryAfter == formatter.date(from:"2026-10-26T00:00:00Z"),"Next local day respects the 25-hour clock-change day")
        let restoredRetry=try JSONDecoder().decode(PAHeartbeatAccount.self,from:JSONEncoder().encode(interruptedCollection))
        precondition(restoredRetry.retryAfter == interruptedCollection.retryAfter && restoredRetry.retryReason == "foreground" && legacy.retryAfter == nil)
        let settled=PAHeartbeatRules.clearWait(restoredRetry)
        precondition(settled.retryAfter == nil && !PAHeartbeatRules.due(settled,now:now.addingTimeInterval(60)),"A settled review returns to its configured interval")
        let quietPartial=PAHeartbeatRules.quiet(lanes,fingerprint:"already-checked",ready:["healthy"],pending:true)
        precondition(quietPartial.mailLanes?["healthy"]?.pending == false && quietPartial.mailLanes?["failed"]?.pending == true && quietPartial.pending == true)
        let quietComplete=PAHeartbeatRules.quiet(quietPartial,fingerprint:"already-checked",ready:["healthy","failed"],pending:false)
        precondition(quietComplete.pending == false && quietComplete.mailLanes?["failed"]?.pending == false,"A quiet complete check clears stale waiting flags")
        precondition(quietComplete.assessed == quietPartial.assessed && quietComplete.mailLanes?["healthy"]?.assessed == quietPartial.mailLanes?["healthy"]?.assessed && quietComplete.calls == quietPartial.calls,"Quiet checks never invent an AI review or reset the allowance")
        precondition(PAHeartbeatRules.quiet(interruptedInference,fingerprint:"new",ready:[],pending:false).phase == "paused")
        print("PASS heartbeat: configurable due boundaries, changed/pending assessment, persisted daily request allowance, day rollover, captured account isolation and interrupted inference requiring explicit resume")
    }
}
